cssCode:
.interactive-wave {
  position: absolute;
  width: 250px;
  height: 250px;
  background: radial-gradient(circle, rgba(255, 0, 128, 0.8), transparent 70%);
  border-radius: 50%;
  opacity: 0.6;
  transition: transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275), opacity 0.4s ease, background 0.4s ease;
  animation: floatWave 5s infinite alternate ease-in-out;
}

/* કન્ટેનર પર ટચ કરવાથી બેકગ્રાઉન્ડમાં થતો ફેરફાર */
#container:hover .interactive-wave, #container:active .interactive-wave {
  transform: scale(2.5);
  opacity: 1;
  background: radial-gradient(circle, rgba(0, 200, 255, 0.8), transparent 70%);
  animation-play-state: paused;
}

@keyframes floatWave {
  0% { transform: translateY(0px) scale(1); }
  100% { transform: translateY(-40px) scale(1.2); }
}

